package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.jsoup.helper.Validate;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class XmlDeclaration_getWholeDeclaration_TriageGen2Test {

    private XmlDeclaration xmlDeclaration;

    @Before
    public void setUp() {
        xmlDeclaration = new XmlDeclaration("xml", "", false);
    }

    @Test
    public void testGetWholeDeclarationWithNameOnly() {
        assertEquals("xml", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclarationWithVersion() {
        xmlDeclaration.attributes().put("version", "1.0");
        assertEquals("xml version=\"1.0\"", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclarationWithEncoding() {
        xmlDeclaration.attributes().put("encoding", "UTF-8");
        assertEquals("xml encoding=\"UTF-8\"", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclarationWithVersionAndEncoding() {
        xmlDeclaration.attributes().put("version", "1.0");
        xmlDeclaration.attributes().put("encoding", "UTF-8");
        assertEquals("xml version=\"1.0\" encoding=\"UTF-8\"", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclarationWithOtherName() {
        xmlDeclaration = new XmlDeclaration("DOCTYPE", "", false);
        assertEquals("DOCTYPE", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclarationWithNoAttributes() {
        assertEquals("xml", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclarationWithNullVersion() {
        xmlDeclaration.attributes().put("version", null);
        assertEquals("xml", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclarationWithNullEncoding() {
        xmlDeclaration.attributes().put("encoding", null);
        assertEquals("xml", xmlDeclaration.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclarationWithNullAttributes() {
        xmlDeclaration = new XmlDeclaration("xml", "", false);
        xmlDeclaration.attributes().clear();
        assertEquals("xml", xmlDeclaration.getWholeDeclaration());
    }
}
